/* ------------------------------------------------------------------ */
/*  Market Recap — renderer (EN / 繁中, dark / light)                   */
/*  Reads data/latest.json (generated by scripts/fetch_data.mjs)        */
/* ------------------------------------------------------------------ */

const $ = (sel) => document.querySelector(sel);

const nf = new Intl.NumberFormat("en-US", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

const fmtPct = (v, digits = 1) =>
  v == null || Number.isNaN(v) ? "n/a" : `${v >= 0 ? "+" : "-"}${Math.abs(v).toFixed(digits)}%`;

const dir = (v) => (v == null ? "flat" : v > 0.0001 ? "up" : v < -0.0001 ? "down" : "flat");

const esc = (s = "") =>
  String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

const money = (v, currency) => `${currency === "HKD" ? "HK$" : "$"}${nf.format(v)}`;

