const state = {
  theme: document.documentElement.dataset.theme === "light" ? "light" : "dark",
  lang: document.documentElement.lang.startsWith("zh") ? "zh" : "en",
};

const t = (key) => I18N[state.lang][key] ?? I18N.en[key] ?? key;

/* ------------------------------- helpers ------------------------------- */

function sparkline(values, cls = "") {
  if (!Array.isArray(values) || values.length < 2) return "";
  const w = 100;
  const h = 28;
  const pad = 2;
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;

  const pts = values.map((v, i) => {
    const x = pad + (i * (w - 2 * pad)) / (values.length - 1);
    const y = pad + (1 - (v - min) / range) * (h - 2 * pad);
    return [x, y];
  });

  const line = pts.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(2)} ${y.toFixed(2)}`).join(" ");
  const area = `${line} L${(w - pad).toFixed(2)} ${h} L${pad} ${h} Z`;

  return `<svg class="spark ${cls}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true">
    <path class="area" d="${area}" />
    <path class="line" d="${line}" />
  </svg>`;
}

function headlineKey(d) {
  const spx = d.indices.find((i) => i.sym === "^GSPC");
  const ndx = d.indices.find((i) => i.sym === "^IXIC");
  const week = spx?.weekChangePct ?? 0;

  if (ndx.changePct > 0.8 && week < 0) return "chipsWeekRed";
  if (ndx.changePct > 0.8) return "chipsUp";
  if (spx.changePct > 0 && week < 0) return "bounceWeekRed";
  if (spx.changePct > 0) return "up";
  if (week < 0) return "slipWeekRed";
  return "mixed";
}

const toneClass = (tone) => (/risk-on/i.test(tone) ? "up" : /risk-off/i.test(tone) ? "down" : "mixed");

const noteFor = (d) =>
  d.meta.weekend ? t("usClosedWeekend") : d.meta.sessionDate === d.meta.todayET ? t("usLatest") : t("usClosed");

/* -------------------------------- static -------------------------------- */

function applyStatic() {
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.dataset.i18n;
    const val = I18N[state.lang][key];
    if (typeof val === "string") el.textContent = val;
  });

  $("#themeBtn").setAttribute("aria-label", t("themeToggle"));
  $("#themeBtn").setAttribute("title", t("themeToggle"));
  $(".seg").setAttribute("aria-label", t("langGroup"));

  document.querySelectorAll(".seg-btn").forEach((b) => {
    const on = b.dataset.lang === state.lang;
    b.classList.toggle("is-active", on);
    b.setAttribute("aria-pressed", String(on));
  });

  document.title =
    state.lang === "zh" ? "美股 · 港股收市摘要 — 07:00 HKT" : "US + HK Market Recap — 07:00 HKT";
}

/* -------------------------------- render -------------------------------- */

// A run older than this means the 07:00 HKT job stopped, missed, or crashed.
const STALE_HOURS = 36;

const agoLabel = (ms) => {
  const hours = ms / 36e5;
  if (hours < 48) return `${Math.max(1, Math.round(hours))}h`;
  if (hours < 24 * 14) return `${Math.round(hours / 24)}d`;
  return `${(hours / (24 * 7)).toFixed(1)}w`;
};

function renderNotice(d) {
  const el = $("#dataNotice");
  const m = d.meta;
  const parts = [];

  const generated = Date.parse(m.generatedAt);
  if (Number.isFinite(generated) && Date.now() - generated > STALE_HOURS * 36e5) {
    const session = state.lang === "zh" ? m.sessionLabelZh : m.sessionLabel;
    parts.push(t("staleNotice")(agoLabel(Date.now() - generated), session));
  }

  const failed = Array.isArray(m.failures) ? m.failures : [];
  if (failed.length) {
    const total = d.ai.total + d.hk.total + failed.length;
    const list = failed.slice(0, 6).map((f) => f.sym).join(", ") + (failed.length > 6 ? "…" : "");
    parts.push(t("partialNotice")(failed.length, total, list));
  }

  if (!parts.length) {
    el.hidden = true;
    el.textContent = "";
    return;
  }
  el.innerHTML =
    `<span class="notice-mark" aria-hidden="true">!</span><div>${parts.map(esc).join("<br>")}</div>`;
  el.hidden = false;
}

function renderMeta(d) {
  const m = d.meta;
  const tone = toneClass(m.tone);
  const clock = (m.generatedAtHKT.match(/(\d{2}:\d{2})$/) || [])[1] || "";
  const spx = d.indices.find((i) => i.sym === "^GSPC");
  const toneLabel = state.lang === "zh" ? TONE_ZH[m.tone] || m.tone : m.tone;

  $("#syncLabel").textContent = `${t("syncPrefix")} ${clock} HKT`;
  $("#heroDate").textContent = state.lang === "zh" ? `香港時間 ${m.generatedAtHKT}` : `${m.generatedAtHKT} HKT`;
  $("#headline").textContent = t("headline")[headlineKey(d)];

  const session = state.lang === "zh" ? m.sessionLabelZh : m.sessionLabel;
  const note = state.lang === "zh" ? m.noteZh : noteFor(d);
  $("#dek").textContent =
    state.lang === "zh"
      ? `${note}交易日：${session}，收市 ${m.sessionCloseET}。`
      : `${note} Session: ${session}, close ${m.sessionCloseET}.`;

  const tonePill = $("#tonePill");
  tonePill.textContent = `${t("tone")} · ${toneLabel}`;
  tonePill.className = `pill tone ${tone}`;

  $("#sessionPill").textContent = `${t("session")} · ${m.sessionDate}`;
  $("#wordsPill").textContent =
    state.lang === "zh"
      ? `英文 ${m.wordCount} ${t("words")} · ${t("limit")}`
      : `${m.wordCount} ${t("words")} · ${t("limit")}`;

  const toneText = $("#toneText");
  toneText.textContent = toneLabel;
  toneText.className = `v ${tone}`;

  const weekText = $("#weekText");
  weekText.textContent = fmtPct(spx?.weekChangePct);
  weekText.className = `v ${dir(spx?.weekChangePct)}`;

  const up = d.ai.upCount;
  const total = d.ai.total;
  const share = total ? Math.round((up / total) * 100) : 0;
  $("#donut").style.setProperty("--p", share);
  $("#donutValue").textContent = `${up}/${total}`;
  $("#donutValue").className = up >= total / 2 ? "up" : "down";
  $("#aiTotalLabel").textContent = state.lang === "zh" ? `${total} 隻` : `${total} names`;

  $("#sessionLabel").textContent = session;
  $("#closeLabel").textContent = m.sessionCloseET;
  $("#aiBreadth").textContent =
    state.lang === "zh"
      ? `${total} 隻 AI 股中 ${up} 隻上升`
      : up >= total / 2
        ? `${up} of ${total} AI names advanced`
        : `${total - up} of ${total} AI names declined`;

  const hk = d.hk;
  $("#hkSessionLabel").textContent = state.lang === "zh" ? hk.sessionLabelZh : hk.sessionLabel;
  $("#footerStamp").textContent = `${t("generated")} ${m.generatedAtHKT} HKT · ${session} · Yahoo Finance`;
}

function renderTape(d) {
  const items = [
    ...d.indices.map((i) => ({ sym: i.short, val: nf.format(i.price), chg: i.changePct })),
    ...d.hk.indices.map((i) => ({ sym: i.short, val: nf.format(i.price), chg: i.changePct })),
    ...d.ai.highlight.map((a) => ({ sym: a.sym, val: money(a.price, "USD"), chg: a.changePct })),
  ];

  const html = items
    .map(
      (i) =>
        `<span class="tape-item"><b>${esc(i.sym)}</b> ${esc(i.val)} <span class="${dir(
          i.chg,
        )}">${fmtPct(i.chg)}</span></span>`,
    )
    .join("");

  $("#tapeTrack").innerHTML = html + html;
}

function idxCard(i) {
  const name = state.lang === "zh" && i.nameZh ? i.nameZh : i.name;
  return `
      <article class="idx-card ${dir(i.changePct)}">
        <div class="idx-top">
          <span class="idx-name">${esc(name)}</span>
          <span class="idx-sym">${esc(i.short)}</span>
        </div>
        <div class="idx-price">${nf.format(i.price)}</div>
        <div class="idx-row">
          <span class="idx-chg">${fmtPct(i.changePct)}</span>
          <span class="idx-week ${dir(i.weekChangePct)}">5D ${fmtPct(i.weekChangePct)}</span>
        </div>
        <div class="idx-spark">${sparkline(i.spark)}</div>
      </article>`;
}

function renderIndices(d) {
  $("#idxGrid").innerHTML = d.indices.map(idxCard).join("");
}

function renderDrivers(d) {
  const list = d.drivers?.length
    ? d.drivers
        .map(
          (x) => `
        <div class="driver">
          <p>${esc((state.lang === "zh" && x.zh) || x.text)}</p>
          <span class="src">via ${esc(x.publisher)}</span>
        </div>`,
        )
        .join("")
    : `<div class="driver"><p>${esc(t("driversFallback"))}</p></div>`;

  $("#driverList").innerHTML = list;
}

function renderCross(d) {
  $("#crossList").innerHTML = d.crossAsset
    .map((c) => {
      const isYield = c.key === "yield10y";
      const change = isYield ? `${c.changeBp >= 0 ? "+" : ""}${c.changeBp.toFixed(0)}bp` : fmtPct(c.changePct);
      const cdir = dir(isYield ? c.changeBp : c.changePct);
      const label = state.lang === "zh" && c.labelZh ? c.labelZh : c.label;
      return `
        <div class="cross-item">
          <span class="label">${esc(label)}</span>
          <span class="right">
            <span class="value">${esc(c.display)}</span>
            <span class="chg ${cdir}">${change}</span>
          </span>
        </div>`;
    })
    .join("");
}

function moverCard(m, cls) {
  const name = state.lang === "zh" && m.nameZh ? m.nameZh : m.name;
  const reason = (state.lang === "zh" && m.reasonZh) || m.reason;
  return `
        <article class="mover ${cls}">
          <div class="mover-top">
            <div class="mover-id">
              <span class="ticker">${esc(m.sym)}</span>
              <span class="mname">${esc(name)}</span>
            </div>
            <div class="mover-right">
              <span class="mprice">${money(m.price, m.currency)}</span>
              <span class="mpct">${fmtPct(m.changePct)}</span>
            </div>
          </div>
          <p class="reason">${esc(reason)}</p>
          ${m.publisher ? `<span class="src">via ${esc(m.publisher)}</span>` : ""}
        </article>`;
}

function moverColumn(list, title, cls) {
  return `
    <div class="mover-col">
      <div class="col-head">
        <span class="dot ${cls}"></span>${esc(title)}
        <span class="count">${list.length}</span>
      </div>
      ${list.map((m) => moverCard(m, cls)).join("")}
    </div>`;
}

function renderMovers(d) {
  $("#moversGrid").innerHTML =
    moverColumn(d.movers.gainers, t("topGainers"), "up") +
    moverColumn(d.movers.losers, t("topDecliners"), "down");
}

function renderAI(d) {
  $("#aiHighlight").innerHTML = d.ai.highlight
    .map((a) => {
      const category = state.lang === "zh" && a.categoryZh ? a.categoryZh : a.category;
      const reason = (state.lang === "zh" && a.reasonZh) || a.reason;
      return `
      <article class="ai-card ${dir(a.changePct)}">
        <div class="ai-cat">${esc(category)}</div>
        <div class="ai-head">
          <span class="ticker">${esc(a.sym)}</span>
          <span class="ai-pct">${fmtPct(a.changePct)}</span>
        </div>
        <div class="ai-nm">${esc(a.name)}</div>
        <div class="ai-spark">${sparkline(a.spark)}</div>
        <p class="reason">${esc(reason)}</p>
      </article>`;
    })
    .join("");

  $("#aiGroups").innerHTML = d.ai.groups
    .map((g) => {
      const category = state.lang === "zh" && g.categoryZh ? g.categoryZh : g.category;
      const stocks = g.stocks
        .map((s) => {
          const d0 = dir(s.changePct);
          const level = Math.abs(s.changePct) >= 5 ? 3 : Math.abs(s.changePct) >= 2 ? 2 : 1;
          return `
              <div class="tile ${d0}${d0 !== "flat" ? ` ${d0}-${level}` : ""}" title="${esc(
                s.name,
              )} ${fmtPct(s.changePct)}">
                <div class="t">
                  <span class="sym">${esc(s.sym)}</span>
                  <span class="p">${fmtPct(s.changePct)}</span>
                </div>
                <div class="nm">${esc(s.name)}</div>
                <div class="mini">${sparkline(s.spark)}</div>
              </div>`;
        })
        .join("");

      return `
      <div class="ai-group">
        <h4>${esc(category)}</h4>
        <div class="tiles">${stocks}</div>
      </div>`;
    })
    .join("");
}

function renderHK(d) {
  const hk = d.hk;
  $("#hkIdxGrid").innerHTML = hk.indices.map(idxCard).join("");

  const total = hk.total;
  const up = hk.upCount;
  const down = hk.downCount;
  const share = total ? Math.round((up / total) * 100) : 0;
  $("#hkBreadth").innerHTML = `
    <span class="hb-label">${total} ${esc(t("hkFocus"))}</span>
    <div class="hb-bar"><span class="hb-up" style="width:${share}%"></span></div>
    <span class="hb-counts"><span class="up">${up} ▲</span> / <span class="down">${down} ▼</span></span>`;
  $("#hkBreadth").setAttribute(
    "title",
    state.lang === "zh" ? `${total} 隻焦點股：${up} 升、${down} 跌` : `${total} focus stocks: ${up} up, ${down} down`,
  );

  const sameDay = hk.sessionDate === d.meta.sessionDate;
  document.querySelector('[data-i18n="hkNote"]').textContent = sameDay ? t("hkNoteSame") : t("hkNotePrev");

  $("#hkMoversGrid").innerHTML =
    moverColumn(hk.movers.gainers, t("hkGainers"), "up") +
    moverColumn(hk.movers.losers, t("hkDecliners"), "down");
}

/* --------------------------------- brief --------------------------------- */

const currentBrief = (d) => (state.lang === "zh" ? d.briefZh || d.brief : d.brief);

function renderBrief(d) {
  const brief = currentBrief(d);
  $("#briefText").textContent = brief;
  $("#wordBadge").textContent =
    state.lang === "zh" ? `${d.meta.wordCountZh} ${t("chars")}` : `${d.meta.wordCount} ${t("words")}`;
  $("#copyBtn").textContent = t("copy");
  $("#copyBtn").classList.remove("done");
}

/* --------------------------------- theme --------------------------------- */

function setTheme(theme, persist = true) {
  state.theme = theme === "light" ? "light" : "dark";
  document.documentElement.dataset.theme = state.theme;
  if (persist) {
    try {
      localStorage.setItem("recap-theme", state.theme);
    } catch (e) {}
  }
}

function setLang(lang, persist = true) {
  state.lang = lang === "zh" ? "zh" : "en";
  document.documentElement.lang = state.lang === "zh" ? "zh-Hant-HK" : "en";
  if (persist) {
    try {
      localStorage.setItem("recap-lang", state.lang);
    } catch (e) {}
  }
  applyStatic();
  if (DATA) renderAll();
}

function renderAll() {
  applyStatic();
  renderMeta(DATA);
  renderNotice(DATA);
  renderTape(DATA);
  renderIndices(DATA);
  renderDrivers(DATA);
  renderCross(DATA);
  renderMovers(DATA);
  renderAI(DATA);
  renderHK(DATA);
  renderBrief(DATA);
  document.documentElement.dataset.ready = "true";
}

/* --------------------------------- init ---------------------------------- */

let DATA = null;

$("#themeBtn").addEventListener("click", () => setTheme(state.theme === "dark" ? "light" : "dark"));

document.querySelectorAll(".seg-btn").forEach((btn) => {
  btn.addEventListener("click", () => {
    if (btn.dataset.lang !== state.lang) setLang(btn.dataset.lang);
  });
});

$("#copyBtn").addEventListener("click", async (e) => {
  const btn = e.currentTarget;
  if (!DATA) return;
  const text = currentBrief(DATA);
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    document.execCommand("copy");
    ta.remove();
  }
  btn.textContent = t("copied");
  btn.classList.add("done");
  setTimeout(() => {
    btn.textContent = t("copy");
    btn.classList.remove("done");
  }, 1600);
});

$("#downloadBtn").addEventListener("click", () => {
  if (!DATA) return;
  const suffix = state.lang === "zh" ? "-zh" : "";
  const blob = new Blob([currentBrief(DATA)], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `market-recap-${DATA.meta.sessionDate}${suffix}.md`;
  a.click();
  URL.revokeObjectURL(url);
});

applyStatic();

fetch("data/latest.json", { cache: "no-store" })
  .then((r) => {
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    return r.json();
  })
  .then((d) => {
    DATA = d;
    renderAll();
  })
  .catch((err) => {
    console.error(err);
    $("#briefText").textContent = `Could not load data/latest.json (${err.message}).\nRun: node scripts/fetch_data.mjs`;
    $("#syncLabel").textContent = "offline";
  });
